export interface Risk {
  description: string;
  probability: string;
  impact: string;
}

export interface PlanPhase {
  phase_name: string;
  duration: string;
  actions: string[];
}

export interface AlternativePath {
  name: string;
  reasoning: string;
  trade_offs: string;
}

export interface DecisionPathAnalysis {
  diagnosis: string;
  alternatives: AlternativePath[];
  simplification_advice: string;
}

export interface RealityCheckResponse {
  reality_score: number;
  confidence_level: "High" | "Medium" | "Low";
  summary: string;
  assumptions_used: string[];
  risks: Risk[];
  realistic_plan: PlanPhase[];
  stop_signal: string;
  decision_path_analysis?: DecisionPathAnalysis;
}

export interface UserInput {
  plan: string;
  constraints: string;
  resources: string;
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { RealityCheckResponse } from "../types";

const SYSTEM_INSTRUCTION = `
Your purpose is to evaluate plans realistically and help users choose better paths
using evidence-based reasoning. You do not motivate, encourage, or validate ambition.
You audit feasibility and analyze trade-offs.

CORE PRINCIPLES
- Evaluate plans based on real-world constraints, not intent or enthusiasm.
- Prefer conservative, realistic interpretations over optimistic assumptions.
- Treat feasibility as a function of time, scope, dependencies, and human limits.

GROUNDING DISCIPLINE
- Base all reasoning on widely observed real-world patterns such as:
  - Learning and execution timelines
  - Validation and iteration cycles
  - Dependency, hiring, and coordination delays
  - Common failure and breakdown patterns
- Do not rely on anecdotes or exceptional cases.
- If a plan contradicts commonly reported benchmarks, feasibility must be reduced.

ASSUMPTIONS POLICY
- Assume the user is an average individual unless explicitly stated otherwise.
- Assume 2–3 hours of effort per day unless specified.
- Never invent user skills, funding, experience, validation, or external support.
- If critical information is missing, explicitly list assumptions in assumptions_used.

CORE AUDIT DIMENSIONS
All evaluations must consider and balance:
- Clarity of goal and problem definition
- Timeline realism
- Scope versus available capacity
- Dependency and coordination risk
- Resource and cash flow clarity (where applicable)
- Risk concentration and compounding effects

SCORING RULES
- reality_score must reflect feasibility, not ambition.
- Extremely compressed timelines for complex goals must result in very low scores.
- confidence_level must reflect the strength of grounding and assumptions,
  not the user's confidence or intent.

RISK ANALYSIS RULES
- Risks must be concrete, realistic, and aligned with known failure patterns.
- Probability and impact must be logically consistent with each risk.
- Multiple high-probability risks must compound into lower feasibility.

PLAN REVISION RULES
- realistic_plan must align with realistic learning curves and execution timelines.
- Reduce scope OR extend time; do not do both aggressively.
- Do not promise outcomes that contradict real-world constraints or norms.

STOP SIGNAL RULES
- stop_signal must clearly define when continued effort would likely waste
  time, money, or opportunity.
- Stop conditions must be measurable, practical, and unambiguous.

DECISION PATH ANALYSIS MODE
When performing Decision Path Analysis:
- Do not predict success or failure.
- Diagnose why the current path fails or struggles.
- Propose a maximum of two alternative paths.
- Explain why an alternative improves feasibility.
- Analyze likely trade-offs and consequences, not outcomes.
- Favor simplification, dependency reduction, and scope control.
- Explicitly identify overengineering risk and simplification advice.

TONE AND BEHAVIOR
- Be professional, neutral, and analytical.
- Do not use motivational, emotional, or judgmental language.
- Do not insult, shame, or pressure the user.
- Provide clarity, not reassurance.
`;

const responseSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    reality_score: { type: Type.INTEGER, description: "A score from 0 to 100 representing realistic feasibility." },
    confidence_level: { type: Type.STRING, enum: ["High", "Medium", "Low"] },
    summary: { type: Type.STRING, description: "A concise, neutral summary of the audit." },
    assumptions_used: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING },
      description: "List of assumptions made about the user's skills, time, or resources."
    },
    risks: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          description: { type: Type.STRING },
          probability: { type: Type.STRING, enum: ["High", "Medium", "Low"] },
          impact: { type: Type.STRING, enum: ["High", "Medium", "Low"] },
        },
        required: ["description", "probability", "impact"],
      },
    },
    realistic_plan: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          phase_name: { type: Type.STRING },
          duration: { type: Type.STRING },
          actions: { type: Type.ARRAY, items: { type: Type.STRING } },
        },
        required: ["phase_name", "duration", "actions"],
      },
    },
    stop_signal: { type: Type.STRING, description: "Clear condition to stop." },
    decision_path_analysis: {
      type: Type.OBJECT,
      properties: {
        diagnosis: { type: Type.STRING },
        alternatives: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              reasoning: { type: Type.STRING },
              trade_offs: { type: Type.STRING },
            },
            required: ["name", "reasoning", "trade_offs"]
          },
        },
        simplification_advice: { type: Type.STRING },
      },
      required: ["diagnosis", "alternatives", "simplification_advice"],
    },
  },
  required: [
    "reality_score",
    "confidence_level",
    "summary",
    "assumptions_used",
    "risks",
    "realistic_plan",
    "stop_signal",
    "decision_path_analysis"
  ],
};

export const auditPlan = async (
  plan: string,
  constraints: string,
  resources: string
): Promise<RealityCheckResponse> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key is missing.");
  }

  const ai = new GoogleGenAI({ apiKey });

  // Use gemini-3-pro-preview for complex reasoning tasks as per guidelines
  const modelName = "gemini-3-pro-preview";

  const prompt = `
    User Plan: ${plan}

    Constraints/Context: ${constraints || "None provided"}

    Resources/Assets: ${resources || "None provided"}

    Perform a rigorous Reality Check and Decision Path Analysis on this plan.
  `;

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        thinkingConfig: { thinkingBudget: 4096 } // Enable thinking for deeper analysis
      },
    });

    const text = response.text;
    if (!text) {
      throw new Error("No response generated.");
    }

    return JSON.parse(text) as RealityCheckResponse;
  } catch (error) {
    console.error("Audit failed:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { UserInput } from '../types';
import { PlayCircle, ShieldAlert, Loader2 } from 'lucide-react';

interface InputFormProps {
  onSubmit: (data: UserInput) => void;
  isLoading: boolean;
}

export const InputForm: React.FC<InputFormProps> = ({ onSubmit, isLoading }) => {
  const [plan, setPlan] = useState('');
  const [constraints, setConstraints] = useState('');
  const [resources, setResources] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!plan.trim()) return;
    onSubmit({ plan, constraints, resources });
  };

  return (
    <div className="w-full max-w-3xl mx-auto bg-slate-800 p-6 md:p-8 rounded-xl border border-slate-700 shadow-xl">
      <div className="flex items-center gap-3 mb-6">
        <ShieldAlert className="text-orange-500 w-8 h-8" />
        <h2 className="text-2xl font-bold text-slate-100">Plan Audit</h2>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div>
          <label htmlFor="plan" className="block text-sm font-medium text-slate-300 mb-2">
            What is your goal or plan? (Be specific)
          </label>
          <textarea
            id="plan"
            required
            rows={5}
            className="w-full bg-slate-900 border border-slate-700 rounded-lg p-4 text-slate-200 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition"
            placeholder="e.g., I want to build a SaaS app in 2 months and get 100 paying customers..."
            value={plan}
            onChange={(e) => setPlan(e.target.value)}
          />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <label htmlFor="constraints" className="block text-sm font-medium text-slate-300 mb-2">
              Time constraints & Commitments
            </label>
            <input
              type="text"
              id="constraints"
              className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-slate-200 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition"
              placeholder="e.g., 2 hours/day, full-time job..."
              value={constraints}
              onChange={(e) => setConstraints(e.target.value)}
            />
          </div>
          <div>
            <label htmlFor="resources" className="block text-sm font-medium text-slate-300 mb-2">
              Available Resources & Skills
            </label>
            <input
              type="text"
              id="resources"
              className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-slate-200 placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition"
              placeholder="e.g., $500 budget, Junior React dev..."
              value={resources}
              onChange={(e) => setResources(e.target.value)}
            />
          </div>
        </div>

        <button
          type="submit"
          disabled={isLoading || !plan.trim()}
          className={`w-full py-4 rounded-lg font-bold text-lg flex items-center justify-center gap-2 transition-all ${
            isLoading || !plan.trim()
              ? 'bg-slate-700 text-slate-400 cursor-not-allowed'
              : 'bg-blue-600 hover:bg-blue-500 text-white shadow-lg shadow-blue-900/20'
          }`}
        >
          {isLoading ? (
            <>
              <Loader2 className="w-5 h-5 animate-spin" />
              Auditing Reality...
            </>
          ) : (
            <>
              <PlayCircle className="w-5 h-5" />
              Run Reality Check
            </>
          )}
        </button>
      </form>

      <div className="mt-6 text-xs text-slate-500 text-center">
        This system audits feasibility. It does not provide motivation. Expect harsh truths.
      </div>
    </div>
  );
};

import React from 'react';
import { RealityCheckResponse } from '../types';
import { AlertTriangle, CheckCircle2, XCircle } from 'lucide-react';

interface ScoreCardProps {
  data: RealityCheckResponse;
}

export const ScoreCard: React.FC<ScoreCardProps> = ({ data }) => {
  const getScoreColor = (score: number) => {
    if (score >= 75) return 'text-green-500 border-green-500/20 bg-green-500/10';
    if (score >= 40) return 'text-yellow-500 border-yellow-500/20 bg-yellow-500/10';
    return 'text-red-500 border-red-500/20 bg-red-500/10';
  };

  const scoreColorClass = getScoreColor(data.reality_score);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
      {/* Main Score */}
      <div className={`col-span-1 rounded-xl border p-6 flex flex-col items-center justify-center text-center ${scoreColorClass}`}>
        <div className="text-sm font-medium uppercase tracking-wider mb-2 opacity-80">Reality Score</div>
        <div className="text-6xl font-black mb-2">{data.reality_score}</div>
        <div className="text-sm font-semibold opacity-90">Confidence: {data.confidence_level}</div>
      </div>

      {/* Summary */}
      <div className="col-span-1 lg:col-span-2 bg-slate-800 rounded-xl border border-slate-700 p-6 flex flex-col justify-between">
        <div>
          <h3 className="text-lg font-semibold text-slate-100 mb-3 flex items-center gap-2">
            <span className="w-2 h-6 bg-blue-500 rounded-full"></span>
            Audit Summary
          </h3>
          <p className="text-slate-300 leading-relaxed text-sm md:text-base">
            {data.summary}
          </p>
        </div>

        <div className="mt-6 pt-4 border-t border-slate-700">
             <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Key Assumptions</h4>
             <div className="flex flex-wrap gap-2">
                {data.assumptions_used.map((assumption, idx) => (
                    <span key={idx} className="text-xs bg-slate-900 text-slate-400 px-2 py-1 rounded border border-slate-700">
                        {assumption}
                    </span>
                ))}
             </div>
        </div>
      </div>

       {/* Stop Signal - Critical Feature */}
       <div className="col-span-1 lg:col-span-3 bg-red-950/30 border border-red-900/50 rounded-xl p-4 flex items-start gap-4">
            <XCircle className="w-6 h-6 text-red-500 shrink-0 mt-0.5" />
            <div>
                <h4 className="text-red-400 font-bold text-sm uppercase tracking-wide">Stop Signal</h4>
                <p className="text-red-200/80 text-sm mt-1">{data.stop_signal}</p>
            </div>
       </div>
    </div>
  );
};

import React from 'react';
import { Risk } from '../types';
import { AlertTriangle } from 'lucide-react';

interface RiskAnalysisProps {
  risks: Risk[];
}

export const RiskAnalysis: React.FC<RiskAnalysisProps> = ({ risks }) => {
  const getSeverityColor = (severity: string) => {
    switch (severity.toLowerCase()) {
      case 'high': return 'text-red-400 bg-red-950/40 border-red-900';
      case 'medium': return 'text-yellow-400 bg-yellow-950/40 border-yellow-900';
      case 'low': return 'text-green-400 bg-green-950/40 border-green-900';
      default: return 'text-slate-400 bg-slate-900 border-slate-800';
    }
  };

  return (
    <div className="bg-slate-800 rounded-xl border border-slate-700 overflow-hidden mb-8">
      <div className="p-6 border-b border-slate-700 flex items-center gap-2">
        <AlertTriangle className="w-5 h-5 text-orange-500" />
        <h3 className="text-lg font-semibold text-slate-100">Risk Assessment</h3>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-left text-sm text-slate-400">
          <thead className="bg-slate-900 uppercase text-xs font-semibold text-slate-500">
            <tr>
              <th className="px-6 py-4">Risk Description</th>
              <th className="px-6 py-4 w-32">Probability</th>
              <th className="px-6 py-4 w-32">Impact</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-700/50">
            {risks.map((risk, idx) => (
              <tr key={idx} className="hover:bg-slate-700/20 transition-colors">
                <td className="px-6 py-4 text-slate-200">{risk.description}</td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-1 rounded text-xs border font-medium ${getSeverityColor(risk.probability)}`}>
                    {risk.probability}
                  </span>
                </td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-1 rounded text-xs border font-medium ${getSeverityColor(risk.impact)}`}>
                    {risk.impact}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

