import React, { useState } from 'react';
import { InputForm } from './components/InputForm';
import { ScoreCard } from './components/ScoreCard';
import { RiskAnalysis } from './components/RiskAnalysis';
import { PlanTimeline } from './components/PlanTimeline';
import { DecisionAnalysis } from './components/DecisionAnalysis';
import { auditPlan } from './services/geminiService';
import { RealityCheckResponse, UserInput } from './types';
import { Activity, Github } from 'lucide-react';

const App: React.FC = () => {
  const [result, setResult] = useState<RealityCheckResponse | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [mode, setMode] = useState<'audit' | 'decision'>('audit');

  const handleAudit = async (input: UserInput) => {
    setIsLoading(true);
    setError(null);
    setResult(null);
    try {
      const data = await auditPlan(input.plan, input.constraints, input.resources);
      setResult(data);
    } catch (err: any) {
      setError(err.message || "An unexpected error occurred while auditing your plan.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleReset = () => {
    setResult(null);
    setError(null);
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-100 pb-20">
      {/* Header */}
      <header className="border-b border-slate-800 bg-slate-900/50 backdrop-blur-sm sticky top-0 z-10">
        <div className="max-w-6xl mx-auto px-4 md:px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2" onClick={handleReset} role="button">
            <div className="bg-blue-600 p-1.5 rounded-lg">
              <Activity className="w-5 h-5 text-white" />
            </div>
            <h1 className="text-xl font-bold tracking-tight">Reality Check<span className="text-blue-500">.ai</span></h1>
          </div>
          <a href="https://github.com/itssagarK/Reality-check-2.git" target="_blank" rel="noopener noreferrer" className="text-slate-400 hover:text-white transition-colors">
            <Github className="w-6 h-6" />
          </a>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 md:px-6 pt-12">
        {!result && (
          <div className="flex flex-col items-center animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="text-center mb-10 max-w-2xl">
              <h2 className="text-4xl md:text-5xl font-black mb-4 bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-indigo-400">
                Kill your delusions.
              </h2>
              <p className="text-lg text-slate-400">
                Most plans fail because of optimism bias. This tool uses AI to simulate failure modes, audit feasibility, and force you to face reality before you commit resources.
              </p>
            </div>

            <InputForm onSubmit={handleAudit} isLoading={isLoading} />

            {error && (
              <div className="mt-8 w-full max-w-2xl p-4 bg-red-900/20 border border-red-800 rounded-lg text-red-200 text-center">
                {error}
              </div>
            )}
          </div>
        )}

        {result && (
          <div className="animate-in fade-in duration-700 space-y-8">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-2">
                <button 
                    onClick={handleReset}
                    className="text-slate-400 hover:text-white text-sm font-medium flex items-center gap-1 hover:underline underline-offset-4"
                >
                    ← Audit another plan
                </button>

                {result.decision_path_analysis && (
                    <div className="bg-slate-900/50 p-1 rounded-lg border border-slate-800 flex items-center">
                        <button 
                            onClick={() => setMode('audit')}
                            className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${mode === 'audit' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-400 hover:text-slate-200'}`}
                        >
                            Audit Report
                        </button>
                        <button 
                            onClick={() => setMode('decision')}
                            className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${mode === 'decision' ? 'bg-indigo-600/20 text-indigo-200 border border-indigo-500/30' : 'text-slate-400 hover:text-slate-200'}`}
                        >
                            Decision Paths
                        </button>
                    </div>
                )}
            </div>

            {mode === 'audit' ? (
                <>
                    <ScoreCard data={result} />
                    <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
                        <RiskAnalysis risks={result.risks} />
                        <PlanTimeline phases={result.realistic_plan} />
                    </div>
                </>
            ) : (
                result.decision_path_analysis && <DecisionAnalysis analysis={result.decision_path_analysis} />
            )}

          </div>
        )}
      </main>
    </div>
  );
