        <div className="bg-slate-950/50 rounded-xl border border-slate-800/50 p-5 relative z-10 flex gap-4">
             <div className="shrink-0 mt-1">
                <Lightbulb className="w-5 h-5 text-yellow-500" />
             </div>
             <div>
                 <h4 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-2">Simplification Advice</h4>
                 <p className="text-slate-200 italic text-sm">
                    "{analysis.simplification_advice}"
                 </p>
             </div>
        </div>
      </div>

      {/* Alternative Paths */}
      <h3 className="text-lg font-bold text-slate-200 px-2 flex items-center gap-2">
         <GitBranch className="w-5 h-5 text-indigo-400" />
         Recommended Alternatives
      </h3>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {analysis.alternatives.map((alt, idx) => (
            <div key={idx} className="bg-slate-900/60 backdrop-blur-md rounded-2xl border border-slate-700/50 p-6 flex flex-col h-full hover:border-indigo-500/40 hover:bg-slate-800/60 transition-all duration-300 group shadow-lg">
                <div className="flex items-center justify-between mb-4 pb-4 border-b border-slate-800/50">
                    <h4 className="text-lg font-bold text-indigo-100 group-hover:text-indigo-300 transition-colors">{alt.name}</h4>
                    <span className="text-xs font-bold bg-indigo-500/10 text-indigo-400 px-2 py-1 rounded border border-indigo-500/20">Path {idx + 1}</span>
                </div>

                <p className="text-sm text-slate-300 mb-6 flex-grow leading-relaxed">
                    {alt.reasoning}
                </p>

                <div className="mt-auto bg-slate-950/50 p-4 rounded-xl border border-slate-800/50 group-hover:border-slate-700 transition-colors">
                    <span className="text-[10px] font-bold text-slate-500 uppercase block mb-2 tracking-wider">Required Trade-offs</span>
                    <p className="text-xs text-slate-400 leading-normal">{alt.trade_offs}</p>
                </div>
            </div>
        ))}
      </div>

    </div>
  );
};
